<template><div class="h-full flex flex-col p-4 sm:p-6" v-if="server"><div class="flex items-center justify-between mb-4"><div><h1 class="text-xl font-bold text-white">คอนโซล</h1><p class="text-dark-500 text-xs mt-1">{{ connected ? 'เชื่อมต่อ log แล้ว' : 'รอการเชื่อมต่อ…' }}</p></div><div class="flex gap-2"><button v-for="command in shortcuts" :key="command" class="shortcut" @click="send(command)">{{ command }}</button></div></div><div ref="logBox" class="flex-1 min-h-72 rounded-xl border border-dark-700 bg-[#080b0d] p-4 overflow-auto font-mono text-xs leading-5 whitespace-pre-wrap"><p v-for="(line,i) in lines" :key="i" :class="line.kind">{{line.text}}</p><p v-if="!lines.length" class="text-dark-500">{{ server.status==='running' ? 'กำลังรอ log…' : 'เริ่มเซิร์ฟเวอร์ก่อนเพื่อใช้งานคอนโซล' }}</p></div><form class="flex gap-2 mt-3" @submit.prevent="send(command)"><input v-model="command" :disabled="server.status!=='running'" class="flex-1 rounded-xl bg-dark-800 border border-dark-600 px-4 py-3 font-mono text-sm text-white outline-none focus:border-mc-green disabled:opacity-50" placeholder="พิมพ์คำสั่ง เช่น say Hello (ไม่ต้องใส่ /)"/><button :disabled="!command.trim() || server.status!=='running'" class="rounded-xl bg-mc-green px-5 text-dark-950 font-semibold disabled:opacity-50">ส่ง</button></form><p v-if="error" class="text-red-300 text-sm mt-2">{{error}}</p></div></template>
<script setup lang="ts">definePageMeta({layout:'server'});const route=useRoute(),store=useServersStore(),id=route.params.id as string;const server=computed(()=>store.servers.find(s=>s.id===id));const lines=ref<{text:string,kind:string}[]>([]),command=ref(''),error=ref(''),connected=ref(false),logBox=ref<HTMLElement>();let socket:WebSocket|undefined;const shortcuts=['list','save-all','whitelist list'];function add(text:string,kind='text'){for(const line of text.split(/\r?\n/)){if(line)lines.value.push({text:line,kind});}if(lines.value.length>1000)lines.value.splice(0,lines.value.length-1000);nextTick(()=>{if(logBox.value)logBox.value.scrollTop=logBox.value.scrollHeight})}function connect(){if(server.value?.status!=='running')return;const protocol=location.protocol==='https:'?'wss:':'ws:';socket=new WebSocket(`${protocol}//${location.host}/api/servers/${id}/console`);socket.onopen=()=>connected.value=true;socket.onclose=()=>{connected.value=false};socket.onerror=()=>add('เชื่อมต่อคอนโซลไม่สำเร็จ','error');socket.onmessage=e=>{try{const data=JSON.parse(e.data);add(data.data,data.type==='error'?'error':'text')}catch{add(e.data)}}}async function send(value:string){const trimmed=value.trim();if(!trimmed)return;error.value='';command.value='';add(`> ${trimmed}`,'command');try{const result=await $fetch(`/api/servers/${id}/command`,{method:'POST',body:{command:trimmed}})as any;if(result.output)add(result.output,'output')}catch(e:any){error.value=e?.data?.statusMessage||'ส่งคำสั่งไม่สำเร็จ'}}onMounted(async()=>{await store.fetchServer(id);connect()});onBeforeUnmount(()=>socket?.close())</script><style scoped>.text{@apply text-slate-300}.command{@apply text-mc-green}.output{@apply text-sky-300}.error{@apply text-red-400}.shortcut{@apply rounded-lg bg-dark-800 hover:bg-dark-700 border border-dark-700 px-2 py-1 text-xs text-dark-300}</style>
